class Solution {
public:
    vector<int> findLonely(vector<int>& nums) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        vector<int> res;
        for (auto& [x, c] : cnt) {
            if (c == 1 && cnt.find(x - 1) == cnt.end() && cnt.find(x + 1) == cnt.end()) {
                res.push_back(x);
            }
        }
        return res;
    }
};
